"""Password registration and login verification functions following org-owasp policy."""
import password_store as _store


def register_password(password: str) -> str:
    """Hash a new password for storage using the current recommended algorithm and parameters."""
    # Use the application-facing API for new password hashing
    return _store.hash_new_password(password)


def check_login(password: str, stored: str) -> bool:
    """Verify a login attempt against any stored password hash format."""
    # Use the application-facing API for verification of any stored format
    return _store.verify_password(password, stored)
